#![forbid(unsafe_code)]
//! Byte-for-byte cross-compatibility golden vectors generated by the Python reference suite
//! (`crypto_util.py`, `node_daemon.py`, `mcc_e2e.py`, `mcc_privacy.py`, `universal_cascade.py`).

use cco_crypto::{
    MccCapsulePurpose, UNIVERSAL_CASCADE_CAPSULE_AAD, X25519SecretKey, aes256_gcm_decrypt,
    aes256_gcm_encrypt_with_nonce, decode_canonical_hex, derive_mcc_capsule_key,
    derive_mcc_forward_key, derive_mgmt_key, derive_universal_cascade_capsule_key,
    derive_universal_cascade_route_key, mcc_capsule_aad, mgmt_auth_aad,
    universal_cascade_packet_aad,
};

#[test]
fn python_reference_x25519_hkdf_aes_gcm_golden_vectors() {
    let a_bytes: [u8; 32] = core::array::from_fn(|i| (i + 1) as u8);
    let b_bytes: [u8; 32] = core::array::from_fn(|i| (i + 33) as u8);
    let a_sk = X25519SecretKey::from_bytes(a_bytes);
    let b_sk = X25519SecretKey::from_bytes(b_bytes);
    let a_pk = a_sk.public_key();
    let b_pk = b_sk.public_key();

    assert_eq!(
        a_pk.to_hex(),
        "07a37cbc142093c8b755dc1b10e86cb426374ad16aa853ed0bdfc0b2b86d1c7c"
    );
    assert_eq!(
        b_pk.to_hex(),
        "5869aff450549732cbaaed5e5df9b30a6da31cb0e5742bad5ad4a1a768f1a67b"
    );

    let shared = a_sk.diffie_hellman(&b_pk).unwrap();
    assert_eq!(
        hex::encode(shared.as_bytes()),
        "a84dc7c3c8f058b1b2dc4cd1e9b5dc0a7987f88b6a9564cde3391fc421159e77"
    );

    let ni = decode_canonical_hex::<16>("00112233445566778899aabbccddeeff").unwrap();
    let nr = decode_canonical_hex::<16>("ffeeddccbbaa99887766554433221100").unwrap();
    let nonce = decode_canonical_hex::<12>("a1a2a3a4a5a6a7a8a9aaabac").unwrap();

    // 1. MGMT KDF + AES-256-GCM
    let mgmt_key = derive_mgmt_key(&shared, &ni, &nr, "A-B").unwrap();
    assert_eq!(
        hex::encode(mgmt_key.as_bytes()),
        "b3a51203a6f9f04da7be7a56766a2a67630bae3265aa112f4377093b8599a966"
    );
    let mgmt_aad = mgmt_auth_aad("A-B", "A", "B", "sid01");
    let mgmt_ct =
        aes256_gcm_encrypt_with_nonce(&mgmt_key, &nonce, b"ID=A|AUTH=test", &mgmt_aad).unwrap();
    assert_eq!(
        hex::encode(&mgmt_ct),
        "86c0a0d417067abdf4b24311da8ac446c83724ec4d580f768ec0e3a6e592"
    );
    assert_eq!(
        aes256_gcm_decrypt(&mgmt_key, &nonce, &mgmt_ct, &mgmt_aad).unwrap(),
        b"ID=A|AUTH=test"
    );

    // 2. MCC forward key (`mcc-a-b-forward-v1`) & MCC recipient capsule (`mcc-recipient-capsule/v1`)
    let ctx = "ctx-golden-01";
    let mcc_fwd = derive_mcc_forward_key(&shared, ctx).unwrap();
    assert_eq!(
        hex::encode(mcc_fwd.as_bytes()),
        "6ac894fb96c21167df3d4c5708d5877b79da02c79ab90fe4196194380ab5413e"
    );
    let mcc_aad = mcc_capsule_aad(ctx, MccCapsulePurpose::Endpoint).unwrap();
    assert_eq!(
        mcc_aad,
        br#"{"context":"ctx-golden-01","domain":"mcc-recipient-capsule","purpose":"endpoint","version":1}"#
    );
    let mcc_cap_key = derive_mcc_capsule_key(&shared, &a_pk, &b_pk, &mcc_aad).unwrap();
    assert_eq!(
        hex::encode(mcc_cap_key.as_bytes()),
        "22c825b840f8631dba1b011001eb76ce9cae16baa20dab3bc689f4308c036cf3"
    );
    let mcc_cap_ct =
        aes256_gcm_encrypt_with_nonce(&mcc_cap_key, &nonce, br#"{"k":"v"}"#, &mcc_aad).unwrap();
    assert_eq!(
        hex::encode(&mcc_cap_ct),
        "9313ae76976469ceacbbd979dbd68ade3ff7c46929877bfc00"
    );

    // 3. Universal H-hop Cascade capsule & route key & packet AEAD
    let uc_cap_key = derive_universal_cascade_capsule_key(&shared, &a_pk, &b_pk).unwrap();
    assert_eq!(
        hex::encode(uc_cap_key.as_bytes()),
        "bea4f1562acafa5f5f9b06ceddc29ac225311e8f2cecc75be9806ccabdf382a8"
    );
    let uc_cap_ct = aes256_gcm_encrypt_with_nonce(
        &uc_cap_key,
        &nonce,
        br#"{"src":"A"}"#,
        UNIVERSAL_CASCADE_CAPSULE_AAD,
    )
    .unwrap();
    assert_eq!(
        hex::encode(&uc_cap_ct),
        "3807884992727d9403fc3f43111e11def96f2c929226393156574b"
    );

    let route_tag = "0123456789abcdef0123456789abcdef";
    let route_tag_bytes = decode_canonical_hex::<16>(route_tag).unwrap();
    let uc_route_key = derive_universal_cascade_route_key(&shared, &route_tag_bytes).unwrap();
    assert_eq!(
        hex::encode(uc_route_key.as_bytes()),
        "42565dcf9e74da26a1961025c2366478bb5c339d504ef4f2e592d4fb5f007a88"
    );
    let uc_pkt_aad = universal_cascade_packet_aad(route_tag, "fwd", 7);
    assert_eq!(
        uc_pkt_aad,
        b"universal-cascade-data-v1:0123456789abcdef0123456789abcdef:fwd:7"
    );
    let uc_pkt_ct = aes256_gcm_encrypt_with_nonce(
        &uc_route_key,
        &nonce,
        br#"{"payload":"aGVsbG8=","metadata":{}}"#,
        &uc_pkt_aad,
    )
    .unwrap();
    assert_eq!(
        hex::encode(&uc_pkt_ct),
        "ab19dcdf89c33b73426e6fd34974bd34f7ba96bc42cd90b3f1d869f472918e8c79291f5f9186049716e2c6a227a7308939d5f13f"
    );
}
